import React,{useState,useEffect,useRef,useMemo} from 'react'
import {createRoot} from 'react-dom/client'
import {QueryClient,QueryClientProvider,useQuery,useQueryClient} from '@tanstack/react-query'
import {useReactTable,getCoreRowModel,flexRender,createColumnHelper} from '@tanstack/react-table'
import {useEditor,EditorContent} from '@tiptap/react'
import StarterKit from '@tiptap/starter-kit'
import {LayoutDashboard,CalendarDays,FolderOpen,BookOpen,Settings,Plus,Search,ArrowLeft,FileText,Upload,Check,ShieldCheck,Clock,AlertCircle,ChevronRight,ChevronLeft,X,Download,LogOut,Building2,Sparkles,LoaderCircle,Paperclip,CheckCircle2,Menu} from 'lucide-react'
import {api,upload,setCsrf,downloadBlob} from './api'
import {Case,Doc,Draft,Redaction,Question,Unit,Job,labels,statusLabel,initials} from './types'
import {textRange,caseYear} from './utils'
import './style.css'
const queryClient=new QueryClient({defaultOptions:{queries:{retry:false,refetchOnWindowFocus:false}}})
let showError:(s:string)=>void=()=>{}
async function action<T,>(fn:()=>Promise<T>,ok?:string){try{const value=await fn();await queryClient.invalidateQueries();if(ok)showError(ok);return value}catch(e){showError(e instanceof Error?e.message:'Operacja nie powiodła się')}}
const date=(s:string)=>new Date(s+'T12:00:00').toLocaleDateString('pl-PL',{day:'numeric',month:'short',year:'numeric'})
const localDay=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Warsaw'}).format(new Date())
function Badge({c}:{c:Case}){return <span className={'badge '+(c.answered&&c.on_time===false?'late':c.state)}>{c.answered?(c.on_time===false?'Wysłano po terminie':'Wysłano w terminie'):c.days!<0?`${Math.abs(c.days!)} dni po terminie`:c.days===0?'Termin dzisiaj':c.days===1?'Termin jutro':`${c.days} dni`}</span>}
function Empty({text}:{text:string}){return <div className="empty"><FolderOpen size={30}/><p>{text}</p></div>}
function Modal({title,children,onClose,wide=false}:{title:string;children:React.ReactNode;onClose:()=>void;wide?:boolean}){return <div className="scrim" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><section role="dialog" aria-modal="true" aria-label={title} className={'modal '+(wide?'wide':'')}><header><h2>{title}</h2><button className="icon" onClick={onClose} aria-label="Zamknij"><X/></button></header>{children}</section></div>}
function FileButton({label='Wgraj dokument',onFile,accept='.pdf,.docx,.doc,.txt'}:{label?:string;onFile:(f:File)=>void;accept?:string}){const ref=useRef<HTMLInputElement>(null);return <><input ref={ref} type="file" accept={accept} className="hidden" onChange={e=>{if(e.target.files?.[0])onFile(e.target.files[0]);e.target.value=''}}/><button className="button secondary" onClick={()=>ref.current?.click()}><Upload size={16}/>{label}</button></>}
function Login({onLogin}:{onLogin:()=>void}){const [username,setUsername]=useState('');const [password,setPassword]=useState('');const [error,setError]=useState('');const [busy,setBusy]=useState(false);return <div className="login"><div className="login-brand"><Building2 size={32}/><span>BYDGOSZCZ<br/><small>URZĄD MIASTA</small></span></div><div className="login-card"><span className="eyebrow">INFORMACJA PUBLICZNA</span><h1>Asystent Urzędnika</h1><p>Sprawy, dokumenty i odpowiedzi.<br/>W jednym, lokalnym środowisku.</p><form onSubmit={async e=>{e.preventDefault();setBusy(true);try{const r=await api('/auth/login','POST',{username,password});setCsrf(r.csrf);onLogin()}catch(e){setError((e as Error).message)}finally{setBusy(false)}}}><label>Login<input autoFocus autoComplete="username" value={username} onChange={e=>setUsername(e.target.value)} required/></label><label>Hasło<input type="password" autoComplete="current-password" value={password} onChange={e=>setPassword(e.target.value)} required/></label>{error&&<p className="error">{error}</p>}<button disabled={busy} className="button primary">{busy?<LoaderCircle className="spin" size={18}/>:<ShieldCheck size={18}/>}Zaloguj się</button></form><small><ShieldCheck size={14}/>Dostęp wyłącznie dla upoważnionych pracowników</small></div></div>}
function App(){const [toast,setToast]=useState('');showError=setToast;useEffect(()=>{if(toast){const t=setTimeout(()=>setToast(''),7000);return()=>clearTimeout(t)}},[toast]);const me=useQuery({queryKey:['me'],queryFn:async()=>{const x=await api('/auth/me');setCsrf(x.csrf);return x}});const [view,setView]=useState('cases');const [selected,setSelected]=useState<string|null>(null);const [create,setCreate]=useState(false);const [calendarImport,setCalendarImport]=useState(false);const [doc,setDoc]=useState<Doc|null>(null);const [mobile,setMobile]=useState(false)
 const cases=useQuery<Case[]>({queryKey:['cases'],queryFn:()=>api('/cases'),enabled:!!me.data});const diagnostics=useQuery({queryKey:['diagnostics'],queryFn:()=>api('/diagnostics'),enabled:!!me.data,refetchInterval:15000});const jobs=useQuery<Job[]>({queryKey:['jobs'],queryFn:()=>api('/jobs'),enabled:!!me.data,refetchInterval:3000});const active=jobs.data?.filter(j=>['queued','running'].includes(j.status))||[];const failed=jobs.data?.find(j=>j.status==='failed');const prior=useRef('');useEffect(()=>{const signature=jobs.data?.map(j=>j.id+j.status).join('')||'';if(prior.current&&prior.current!==signature){queryClient.invalidateQueries({queryKey:['case']});queryClient.invalidateQueries({queryKey:['knowledge']})}prior.current=signature},[jobs.data]);
 if(me.isPending)return <div className="loading"><LoaderCircle className="spin"/>Uruchamianie aplikacji…</div>;
 if(!me.data)return <><Login onLogin={()=>queryClient.invalidateQueries({queryKey:['me']})}/>{toast&&<div role="status" className="toast">{toast}</div>}</>;
 const navigate=(v:string)=>{setView(v);setSelected(null);setMobile(false)};
 return <div className="shell"><aside className={mobile?'open':''}><div className="brand"><div className="brand-symbol"><Building2 size={23}/></div><div>Asystent<small>URZĘDNIKA · BYDGOSZCZ</small></div></div><div className="nav-caption">PRZESTRZEŃ ROBOCZA</div><nav>{[['cases',FolderOpen,'Rejestr wniosków'],['calendar',CalendarDays,'Kalendarium'],['knowledge',BookOpen,'Baza wiedzy'],['settings',Settings,'Diagnostyka']].map(([id,Icon,title])=><button key={id as string} className={view===id?'active':''} onClick={()=>navigate(id as string)}><Icon size={19}/>{title as string}{id==='cases'&&<b>{cases.data?.length||0}</b>}</button>)}</nav><div className="aside-bottom"><div className="local"><ShieldCheck size={18}/><div>Lokalne środowisko<small>Dokumenty pozostają w systemie</small></div></div><div className="account"><span className="avatar">{me.data.username.slice(0,2).toUpperCase()}</span><div>{me.data.username}<small>{me.data.role==='admin'?'Administrator':'Operator UDIP'}</small></div><button className="icon" title="Wyloguj" onClick={()=>action(async()=>{await api('/auth/logout','POST');setCsrf('');queryClient.clear()})}><LogOut size={17}/></button></div></div></aside><main><div className="topbar"><button className="icon mobile-menu" aria-label={mobile?"Zamknij menu nawigacji":"Otwórz menu nawigacji"} aria-expanded={mobile} onClick={()=>setMobile(!mobile)}><Menu/></button><span>Urząd Miasta Bydgoszczy <ChevronRight size={14}/> Informacja publiczna</span><span className="top-right"><i className={diagnostics.data?.ready?'dot ready':'dot'}/>{diagnostics.data?.ready?'Usługi gotowe':'Sprawdź diagnostykę'}<span className="top-date">{date(localDay())}</span></span></div><div className="workspace">{selected?<Detail id={selected} onBack={()=>setSelected(null)} onDoc={setDoc}/>:view==='cases'||view==='calendar'?<Registry cases={cases.data||[]} loading={cases.isPending} error={cases.error?.message} calendar={view==='calendar'} select={setSelected} create={()=>setCreate(true)} importCalendar={me.data.role==='admin'?()=>setCalendarImport(true):undefined}/>:view==='knowledge'?<Knowledge onDoc={setDoc} admin={me.data.role==='admin'}/>:<Diagnostics data={diagnostics.data} jobs={jobs.data||[]}/>}</div>{active.length>0&&<div className="job-strip"><LoaderCircle size={16} className="spin"/>{active.length} zadanie w kolejce / w trakcie przetwarzania lokalnego</div>}{failed&&<div className="job-error"><AlertCircle size={15}/>Ostatnie nieudane zadanie: {failed.result.error}</div>}</main>{create&&<NewCase onClose={()=>setCreate(false)} onCreated={id=>{setCreate(false);setSelected(id)}}/>}{calendarImport&&<CalendarImport onClose={()=>setCalendarImport(false)}/>} {doc&&<DocumentModal doc={doc} onClose={()=>setDoc(null)}/>} {toast&&<div role="status" className="toast" onClick={()=>setToast('')}>{toast}</div>}</div>
}
const column=createColumnHelper<Case>();
function Registry({cases,loading,error,calendar,select,create,importCalendar}:{cases:Case[];loading:boolean;error?:string;calendar:boolean;select:(id:string)=>void;create:()=>void;importCalendar?:()=>void}){const [query,setQuery]=useState('');const [filter,setFilter]=useState('all');const [year,setYear]=useState('all');const [month,setMonth]=useState(localDay().slice(0,7));const rows=useMemo(()=>cases.filter(c=>(year==='all'||caseYear(c)===year)&&(filter==='all'||filter==='open'&&!c.answered||filter==='urgent'&&!c.answered&&c.days!<=1||filter==='closed'&&!!c.answered)&&(`${c.reference} ${c.title} ${c.applicant}`.toLocaleLowerCase('pl').includes(query.toLocaleLowerCase('pl')))),[cases,year,filter,query]);const columns=[column.display({id:'lp',header:'LP.',cell:info=><span className="muted">{info.row.index+1}</span>}),column.accessor('reference',{header:'NUMER SPRAWY',cell:info=><span className="reference">{info.getValue()}<small>{date(info.row.original.received)}</small></span>}),column.accessor('title',{header:'PRZEDMIOT WNIOSKU',cell:info=><span className="subject">{info.getValue()}<small>{info.row.original.applicant||'Wnioskodawca nieoznaczony'}</small></span>}),column.accessor('deadline',{header:'TERMIN ODPOWIEDZI',cell:info=><span>{date(info.getValue())}<small className="muted">{statusLabel(info.row.original)}</small></span>}),column.accessor('state',{header:'TERMIN',cell:info=><Badge c={info.row.original}/>}),column.accessor('answered',{header:'DATA ODPOWIEDZI',cell:info=><span>{info.getValue()?date(info.getValue()!):'—'}</span>}),column.accessor('owner',{header:'PROWADZĄCY',cell:info=><span className="owner" title={info.getValue()||'Nieprzypisany'}><i>{initials(info.getValue()||'')}</i>{info.getValue()||'Nieprzypisany'}</span>})];const table=useReactTable({data:rows,columns,autoResetPageIndex:false,getCoreRowModel:getCoreRowModel()});const open=cases.filter(c=>!c.answered);return <><div className="page-heading"><div><span className="eyebrow">OBSŁUGA INFORMACJI PUBLICZNEJ</span><h1>{calendar?'Kalendarium':'Rejestr wniosków'}</h1><p>{calendar?'Terminy odpowiedzi i najbliższe działania.':'Wszystkie sprawy, terminy i dokumenty w jednym miejscu.'}</p></div><button className="button primary" onClick={create}><Plus size={18}/>Nowy wniosek</button></div><div className="stats"><Stat label="Wszystkie wnioski" value={cases.length} icon={<FolderOpen/>}/><Stat label="W toku" value={open.length} icon={<Clock/>}/><Stat label="Dzisiaj i jutro" value={open.filter(c=>c.days===0||c.days===1).length} icon={<CalendarDays/>}/><Stat label="Po terminie" value={open.filter(c=>c.days!<0).length} icon={<AlertCircle/>} warning/></div><section className="card"><div className="toolbar"><div className="search"><Search size={18}/><input aria-label="Szukaj sprawy" placeholder="Szukaj po numerze, temacie lub wnioskodawcy…" value={query} onChange={e=>setQuery(e.target.value)}/></div><select aria-label="Rok sprawy" value={year} onChange={e=>setYear(e.target.value)}><option value="all">Wszystkie lata</option>{[...new Set(cases.map(caseYear))].sort().reverse().map(y=><option key={y}>{y}</option>)}</select>{importCalendar&&<button className="button subtle" onClick={importCalendar}><Upload size={15}/>Import XLSX</button>}</div><div className="filters">{[['all','Wszystkie'],['open','W toku'],['urgent','Pilne'],['closed','Zakończone']].map(([key,label])=><button className={filter===key?'selected':''} onClick={()=>setFilter(key)} key={key}>{label}</button>)}<span>{rows.length} spraw · od najstarszych</span></div><Legend/>{error?<p className="error pad">{error}</p>:loading?<p className="pad">Wczytywanie rejestru…</p>:calendar?<Calendar cases={rows} month={month} setMonth={setMonth} select={select}/>:<div className="table-wrap"><table><thead>{table.getHeaderGroups().map(g=><tr key={g.id}>{g.headers.map(h=><th key={h.id}>{flexRender(h.column.columnDef.header,h.getContext())}</th>)}<th/></tr>)}</thead><tbody>{table.getRowModel().rows.map(row=><tr key={row.id} className={'row-'+(row.original.answered?'closed':row.original.state)} tabIndex={0} onKeyDown={e=>e.key==='Enter'&&select(row.original.id)} onClick={()=>select(row.original.id)}>{row.getVisibleCells().map(c=><td key={c.id}>{flexRender(c.column.columnDef.cell,c.getContext())}</td>)}<td><ChevronRight size={16}/></td></tr>)}</tbody></table>{!rows.length&&<Empty text="Brak wniosków spełniających wybrane kryteria."/>}</div>}<footer className="card-footer"><ShieldCheck size={15}/>Rejestr jest aktualizowany na podstawie zatwierdzonych danych.</footer></section></>}
function Legend(){return <div className="legend" aria-label="Legenda terminów"><span className="lg overdue">Po terminie</span><span className="lg today">Termin dzisiaj</span><span className="lg tomorrow">Termin jutro</span><span className="lg later">Później</span><span className="lg closed">Odpowiedź wysłana</span></div>}
/** Pismo z zaznaczeniami: szare — propozycja do decyzji, czarne — zaakceptowane do usunięcia. */
function RedactionPreview({text,redactions,disabled,onChange}:{text:string;redactions:Redaction[];disabled:boolean;onChange:(r:Redaction[])=>void}){const chars=Array.from(text);const visible=redactions.map((r,i)=>({...r,i})).filter(r=>r.state!=='rejected').sort((a,b)=>a.start-b.start);const parts:React.ReactNode[]=[];let pos=0;for(const r of visible){if(r.start<pos)continue;parts.push(chars.slice(pos,r.start).join(''));parts.push(<mark key={r.i} className={'pii '+r.state} title={r.category+(r.state==='proposed'?' — kliknij, aby ukryć':' — kliknij, aby pozostawić')} onClick={()=>!disabled&&onChange(redactions.map((x,j)=>j===r.i?{...x,state:x.state==='accepted'?'rejected':'accepted'}:x))}>{chars.slice(r.start,r.end).join('')}</mark>);pos=r.end}parts.push(chars.slice(pos).join(''));const pending=redactions.filter(r=>r.state==='proposed').length;return <div className="evidence"><h3>Podgląd anonimizacji</h3><p className="micro"><mark className="pii proposed">szary</mark> — propozycja systemu do decyzji, <mark className="pii accepted">czarny</mark> — zostanie trwale usunięty z eksportu. Kliknij fragment, aby zmienić decyzję.{pending>0&&<b> Do rozpatrzenia: {pending}.</b>}</p><div className="redaction-preview">{parts}</div>{!disabled&&<button className="button secondary" onClick={()=>{const sel=window.getSelection()?.toString()||'';const range=textRange(text,sel);if(!sel.trim()||!range){showError('Zaznacz myszą fragment w podglądzie powyżej.');return}onChange([...redactions,{...range,state:'accepted',category:'ręcznie',reason:'Wybór operatora'}])}}>Ukryj zaznaczony fragment</button>}</div>}
function Stat({label,value,icon,warning=false}:{label:string;value:number;icon:React.ReactNode;warning?:boolean}){return <div className={'stat '+(warning&&value?'warn':'')}><div><span>{label}</span><strong>{value}</strong></div><div className="stat-icon">{icon}</div></div>}
function Calendar({cases,month,setMonth,select}:{cases:Case[];month:string;setMonth:(s:string)=>void;select:(id:string)=>void}){const [y,m]=month.split('-').map(Number);const first=(new Date(y,m-1,1).getDay()+6)%7;const days=new Date(y,m,0).getDate();return <div className="calendar"><div className="calendar-head"><h3>Terminy odpowiedzi</h3><input aria-label="Miesiąc kalendarium" type="month" value={month} onChange={e=>setMonth(e.target.value||localDay().slice(0,7))}/></div><div className="calendar-grid">{['Pon','Wt','Śr','Czw','Pt','Sob','Niedz'].map(x=><b key={x}>{x}</b>)}{Array.from({length:first},(_,i)=><div className="day blank" key={'b'+i}/>)}{Array.from({length:days},(_,i)=>{const day=`${month}-${String(i+1).padStart(2,'0')}`;return <div key={day} className={'day '+(day===localDay()?'current':'')}><span>{i+1}</span>{cases.filter(c=>c.deadline===day).map(c=><button key={c.id} className={'cal-'+(c.answered?'closed':c.state)} onClick={()=>select(c.id)} title={c.title+' · '+statusLabel(c)+(c.answered?'':c.days!<0?' · po terminie':c.days===0?' · termin dzisiaj':c.days===1?' · termin jutro':'')}>{c.reference}<small>{statusLabel(c)} · {c.title}</small></button>)}</div>})}</div></div>}
function NewCase({onClose,onCreated}:{onClose:()=>void;onCreated:(id:string)=>void}){const [form,setForm]=useState({reference:'',title:'',applicant:'',received:localDay(),owner:'',delivery:''});const [text,setText]=useState('');const [questions,setQuestions]=useState('');const [importId,setImportId]=useState<string|null>(null);const [uploading,setUploading]=useState(false);const [busy,setBusy]=useState(false);const imported=useQuery({queryKey:['import',importId],queryFn:()=>api('/imports/'+importId),enabled:!!importId,refetchInterval:q=>['ready','failed'].includes(q.state.data?.document.state)||q.state.data?.jobs.some((j:Job)=>j.kind==='document'&&j.status==='failed')?false:2000});useEffect(()=>{if(imported.data?.document.state==='ready'){setText(imported.data.document.text);setQuestions(imported.data.questions.map((q:Question)=>q.text).join('\n\n'));const s=imported.data.suggested;if(s)setForm(f=>({...f,reference:f.reference||s.reference,title:f.title||s.title,applicant:f.applicant||s.applicant,received:f.received===localDay()?s.received:f.received}))}},[imported.data?.document.id,imported.data?.document.version,imported.data?.document.state]);const importError=imported.error?.message||imported.data?.jobs.find((j:Job)=>j.kind==='document'&&j.status==='failed')?.result.error;const existingCase=imported.data?.document.case_id;const set=(k:string,v:string)=>setForm(x=>({...x,[k]:v}));const preview=useQuery({queryKey:['deadline',form.received],queryFn:()=>api('/deadline-preview?received='+form.received),enabled:/^\d{4}-\d{2}-\d{2}$/.test(form.received)});return <Modal title="Nowy wniosek o informację publiczną" onClose={onClose} wide><div className="modal-body"><div className="upload-zone"><Upload size={28}/><div><strong>Wgraj wniosek</strong><p>PDF, DOCX, DOC lub TXT · do 20 MB. Dane zatwierdzisz po odczycie.</p></div><FileButton onFile={async f=>{setUploading(true);await action(async()=>{const r=await upload('/imports',f);setImportId(r.document.id)});setUploading(false)}}/></div>{uploading&&<p className="notice">Przesyłanie pliku…</p>}{importError&&<p role="alert" className="notice warning">Nie udało się odczytać dokumentu: {importError}. Wgraj poprawiony plik albo zamknij formularz i zarejestruj wniosek ręcznie.</p>}{existingCase&&<div className="notice warning">Ten plik jest już wnioskiem w zarejestrowanej sprawie.<button className="button secondary" onClick={()=>onCreated(existingCase)}>Otwórz istniejącą sprawę</button></div>}{imported.data&&imported.data.document.state!=='ready'&&!importError&&<p className="notice"><LoaderCircle className="spin" size={16}/>Trwa odczyt dokumentu. Sprawdź zadania w diagnostyce, jeśli plik wymaga korekty.</p>}<form onSubmit={async e=>{e.preventDefault();setBusy(true);const qs=questions.split(/\n\s*\n/).filter(Boolean).map((text,i)=>({id:'q'+(i+1),text,status:'brak_materialu'}));const data={...form,questions:qs};const r=await action(async()=>importId?api('/imports/'+importId+'/confirm','POST',{version:imported.data.document.version,text,case:data,metadata:{}}):api('/cases','POST',data));setBusy(false);if(r)onCreated(r.case_id||r.id)}}><div className="form-grid">{[['reference','Numer sprawy'],['received','Data wpływu'],['applicant','Wnioskodawca'],['owner','Prowadzący']].map(([key,label])=><label key={key}>{label}<input required={['reference','received'].includes(key)} type={key==='received'?'date':'text'} value={form[key as keyof typeof form]} onChange={e=>set(key,e.target.value)}/></label>)}</div><label>Przedmiot wniosku<input required value={form.title} onChange={e=>set('title',e.target.value)}/></label><label>Pytania i żądane dokumenty<small>Oddziel kolejne punkty pustym wierszem.</small><textarea rows={5} value={questions} onChange={e=>setQuestions(e.target.value)}/></label>{importId&&<label>Treść odczytana z dokumentu — sprawdź i popraw<textarea rows={6} value={text} onChange={e=>setText(e.target.value)}/></label>}{imported.data?.suggested&&<p className="notice">Numer, data wpływu, wnioskodawca i przedmiot zostały zaproponowane na podstawie dokumentu — sprawdź je przed zatwierdzeniem.</p>}<p className="notice">Termin odpowiedzi: <b>{preview.data?date(preview.data.deadline):'—'}</b> (14 dni od wpływu, z przesunięciem na dzień roboczy; art. 13 UDIP). Data wpływu i zakres wniosku wymagają potwierdzenia.</p><div className="modal-actions"><button type="button" className="button secondary" onClick={onClose}>Anuluj</button><button className="button primary" disabled={busy||uploading||!!existingCase||!!importError||!!importId&&imported.data?.document.state!=='ready'}><Check size={17}/>Zatwierdź i zarejestruj</button></div></form></div></Modal>}
function Detail({id,onBack,onDoc}:{id:string;onBack:()=>void;onDoc:(d:Doc)=>void}){const result=useQuery<{case:Case;documents:Doc[];drafts:Draft[];events:any[]}>({queryKey:['case',id],queryFn:()=>api('/cases/'+id),refetchInterval:6000});const [tab,setTab]=useState('overview');const [edit,setEdit]=useState(false);const [note,setNote]=useState('');const [noteType,setNoteType]=useState('note');const [all,setAll]=useState(false);const [deadlineModal,setDeadlineModal]=useState(false);const [sentModal,setSentModal]=useState(false);const [suggest,setSuggest]=useState<any[]>([]);const [letter,setLetter]=useState<Draft|null>(null);const [materialUnit,setMaterialUnit]=useState('');const [materialKind,setMaterialKind]=useState('material');const units=useQuery<Unit[]>({queryKey:['units'],queryFn:()=>api('/units')});const similar=useQuery({queryKey:['similar',id,all],queryFn:()=>api(`/cases/${id}/similar?all_archive=${all}`)});if(!result.data)return <p className="pad">{result.error?.message||'Wczytywanie sprawy…'}</p>;const {case:c,documents,drafts,events}=result.data;return <><button className="back" onClick={onBack}><ArrowLeft size={16}/>Rejestr wniosków</button><div className="page-heading detail-heading"><div><span className="eyebrow">{c.reference}</span><h1>{c.title}</h1><p>{c.applicant} · wpływ {date(c.received)} · {c.owner||'Bez prowadzącego'}</p></div><Badge c={c}/></div>{c.warnings.length>0&&<div className="notice warning"><AlertCircle size={18}/><div>{c.warnings.map((w,i)=><p key={i}>{w}</p>)}</div></div>}<div className="detail-summary"><div><small>ETAP SPRAWY</small><strong>{statusLabel(c)}</strong></div><div><small>TERMIN ODPOWIEDZI</small><strong>{date(c.deadline)}</strong>{c.extension_days>0&&<small className="muted">przedłużony o {c.extension_days} dni</small>}</div><div><small>PYTANIA WE WNIOSKU</small><strong>{c.questions.length}</strong></div><div><small>MATERIAŁY</small><strong>{documents.filter(d=>d.active&&d.kind!=='request').length} zatwierdzonych</strong></div></div><div className="tabs">{[['overview','Przebieg i pytania'],['documents','Dokumenty'],['drafts','Odpowiedź'],['archive','Podobne sprawy']].map(([k,title])=><button key={k} className={tab===k?'selected':''} onClick={()=>setTab(k)}>{title}{k==='documents'&&<b>{documents.length}</b>}</button>)}</div>{tab==='overview'?<div className="detail-grid"><div><section className="card pad"><div className="section-heading"><h2>Zakres wniosku</h2><button className="button subtle" onClick={()=>setEdit(true)}>Edytuj dane</button></div>{!c.questions.length?<Empty text="Dodaj pytania, aby kontrolować kompletność odpowiedzi."/>:c.questions.map((q,i)=><div className="question" key={q.id}><span>{String(i+1).padStart(2,'0')}</span><p>{q.text}</p></div>)}</section><section className="card pad"><div className="section-heading"><h2>Jednostki merytoryczne</h2><button className="button secondary" onClick={()=>action(async()=>{const r=await api('/cases/'+id+'/unit-suggestions','POST');setSuggest(r);if(!r.length)showError('Brak dopasowanej jednostki — wybierz jednostkę z listy ręcznie.')})}><Sparkles size={15}/>Podpowiedz jednostki</button></div><div className="unit-list">{units.data?.map(u=><label className="check" key={u.id}><input type="checkbox" checked={c.units.includes(u.id)} onChange={()=>action(()=>api('/cases/'+id,'PATCH',{reference:c.reference,title:c.title,applicant:c.applicant,received:c.received,owner:c.owner,questions:c.questions,delivery:c.delivery,version:c.version,units:c.units.includes(u.id)?c.units.filter(x=>x!==u.id):[...c.units,u.id]}))}/><div>{u.name}<small>{u.description}</small></div></label>)}</div>{suggest.map(u=><div className="notice" key={u.id}><Building2 size={16}/><span><b>{u.name}</b><br/>{u.reason}</span>{c.units.includes(u.id)?<span className="badge zakonczona">Przypisana</span>:<button className="button tiny primary" onClick={()=>action(()=>api('/cases/'+id,'PATCH',{reference:c.reference,title:c.title,applicant:c.applicant,received:c.received,owner:c.owner,questions:c.questions,delivery:c.delivery,version:c.version,units:[...c.units,u.id]}))}>Przypisz</button>}</div>)}{suggest.length===0&&<p className="micro">Podpowiedź uwzględnia kompetencje jednostek (BIP UMB) i jednostki z podobnych spraw. Ostateczny wybór należy do urzędnika.</p>}</section></div><div><section className="card pad"><h2>Terminy i udostępnienie</h2><p className="muted">Pierwotny termin: {date(c.original_deadline)}</p><button className="button secondary full" onClick={()=>setDeadlineModal(true)}><CalendarDays size={16}/>Odnotuj zmianę terminu</button><button className="button secondary full" onClick={()=>setSentModal(true)}><CheckCircle2 size={16}/>Odnotuj wysłanie poza systemem</button><p className="micro">Aplikacja niczego nie wysyła. Zmiana terminu wymaga potwierdzenia powiadomienia wnioskodawcy.</p></section><section className="card pad"><h2>Historia sprawy</h2><select aria-label="Rodzaj zdarzenia" value={noteType} onChange={e=>setNoteType(e.target.value)}><option value="note">Notatka</option><option value="material_requested">Zapytanie do wydziału</option><option value="query">Kwerenda</option><option value="clarification">Doprecyzowanie</option></select><textarea aria-label="Nowa notatka" placeholder="Dodaj informację o wykonanej czynności…" rows={3} value={note} onChange={e=>setNote(e.target.value)}/><button disabled={!note.trim()} className="button secondary full" onClick={()=>action(async()=>{await api('/cases/'+id+'/events','POST',{type:noteType,text:note});setNote('')})}>Zapisz zdarzenie</button><div className="timeline">{events.map(e=><div key={e.id}><i/><b>{({'case_updated':'Zmieniono dane sprawy','manual_draft_created':'Utworzono szkic ręczny','draft_edited':'Zapisano projekt odpowiedzi','redactions_updated':'Zmieniono anonimizację pisma','letter_exported':'Wyeksportowano pismo','attachment_reviewed':'Zapisano przegląd załącznika','attachment_exported':'Utworzono kopię załącznika','attachment_export_approved':'Zatwierdzono kopię załącznika','package_downloaded':'Pobrano pakiet odpowiedzi','note':'Notatka','material_requested':'Zapytanie do wydziału','query':'Kwerenda','clarification':'Doprecyzowanie','case_created':'Zarejestrowano wniosek','document_uploaded':'Dodano dokument','document_confirmed':'Zatwierdzono dokument','draft_generated':'Przygotowano projekt','draft_approved':'Zatwierdzono pismo','deadline_changed':'Zmieniono termin','manually_marked_sent':'Odnotowano udostępnienie','document_retry':'Ponowiono odczyt dokumentu','request_attached':'Dołączono plik wniosku','calendar_imported':'Zaimportowano z kalendarium'} as any)[e.type]||e.type.replaceAll('_',' ')}</b><p>{e.detail.text||(e.type==='deadline_changed'?`${e.detail.reason||''} · nowy termin ${e.detail.deadline?date(e.detail.deadline):''}${e.detail.extension_days?` (+${e.detail.extension_days} dni)`:''}`:e.type==='manually_marked_sent'?`${e.detail.answered?date(e.detail.answered):''} · ${e.detail.delivery||''}`:e.type==='letter_exported'?`Format ${String(e.detail.format||'').toUpperCase()}`:e.detail.reason||'')}</p><small>{new Date(e.created).toLocaleString('pl-PL')} · {e.actor}</small></div>)}</div></section></div></div>:tab==='documents'?<section className="card pad"><div className="section-heading"><div><h2>Materiały i załączniki</h2><p className="muted">Dodaj odpowiedzi jednostek. Każdy odczyt zatwierdź przed użyciem przez AI.</p></div><div className="inline"><select aria-label="Jednostka materiału" value={materialUnit} onChange={e=>setMaterialUnit(e.target.value)}><option value="">Bez jednostki</option>{units.data?.map(u=><option key={u.id} value={u.id}>{u.name}</option>)}</select><select aria-label="Rodzaj dokumentu" value={materialKind} onChange={e=>setMaterialKind(e.target.value)}><option value="material">Odpowiedź wydziału (dla AI)</option><option value="attachment">Załącznik do udostępnienia</option></select><FileButton label="Dodaj dokument" onFile={f=>action(()=>upload('/cases/'+id+'/documents?kind='+materialKind+(materialUnit?'&unit_id='+materialUnit:''),f))}/></div></div><DocumentList docs={documents} onDoc={onDoc}/></section>:tab==='drafts'?<section className="card pad"><div className="section-heading"><div><h2>Projekty odpowiedzi</h2><p className="muted">Generowanie korzysta z zatwierdzonych materiałów bieżącej sprawy.</p></div><div className="inline"><button className="button secondary" onClick={()=>action(async()=>{const d=await api('/cases/'+id+'/manual-drafts','POST');setLetter(d)})}>Nowy szkic ręczny</button><button className="button primary" onClick={()=>action(()=>api('/cases/'+id+'/drafts','POST'),'Zlecono przygotowanie projektu lokalnemu modelowi.')}><Sparkles size={16}/>Przygotuj projekt AI</button></div></div>{drafts.length?drafts.map(d=><button key={d.id} className="draft-row" onClick={()=>setLetter(d)}><FileText/><div><b>Projekt odpowiedzi · wersja {d.version}</b><small>{d.model==='manual'?'Szkic ręczny':`Model lokalny: ${d.model}`} · {d.approved_version===d.version?'Zatwierdzony':'Do sprawdzenia'}</small></div><ChevronRight size={18}/></button>):<Empty text="Nie ma jeszcze projektów odpowiedzi."/>}<PackageDownload caseId={id} exports={(result.data as any).exports||[]} documents={documents}/></section>:<section className="card pad"><div className="section-heading"><div><h2>Podobne sprawy i źródła</h2><p className="muted">{similar.data?.mode==='hybrid'?'Wyszukiwanie hybrydowe: tekst i znaczenie.':'Wyszukiwanie tekstowe.'}</p></div><label className="check"><input type="checkbox" checked={all} onChange={e=>setAll(e.target.checked)}/>Całe archiwum (domyślnie: ostatni rok)</label></div>{similar.data?.warning&&<p className="notice">{similar.data.warning}</p>}{similar.isFetching?<p>Przeszukiwanie lokalnego archiwum…</p>:similar.data?.results.length?similar.data.results.map((r:any)=><article className="search-result" key={r.document_id}><span className="eyebrow">{r.reference}{r.received?' · wpływ '+date(r.received):''} · strona {r.page}{r.similarity!=null?` · podobieństwo ${Math.round(r.similarity*100)}%`:''}</span>{r.matched?.length>0&&<small className="muted">Wspólne pojęcia: {r.matched.join(', ')}</small>}<h3>{r.title}</h3><p>{r.excerpt}</p></article>):<Empty text={all?'Brak podobnych spraw w archiwum.':'Brak podobnych spraw z ostatniego roku. Zaznacz „Całe archiwum”, aby szukać dalej.'}/>}</section>}{edit&&<EditCase c={c} onClose={()=>setEdit(false)}/>} {letter&&<DraftEditor initial={letter} onClose={()=>setLetter(null)}/>} {deadlineModal&&<DeadlineModal c={c} onClose={()=>setDeadlineModal(false)}/>} {sentModal&&<SentModal c={c} onClose={()=>setSentModal(false)}/>}</>}
function PackageDownload({caseId,exports,documents}:{caseId:string;exports:any[];documents:Doc[]}){const [letter,setLetter]=useState('');const [selected,setSelected]=useState<string[]>([]);const letters=exports.filter(e=>e.draft_id&&e.approved);const docs=exports.filter(e=>e.document_id&&e.approved);return <div className="evidence"><h3>Pakiet odpowiedzi z załącznikami</h3><p className="micro">Wybierz zatwierdzone kopie. System sprawdzi ich aktualność przed pobraniem ZIP.</p><label>Eksport pisma<select value={letter} onChange={e=>setLetter(e.target.value)}><option value="">Wybierz wygenerowany eksport</option>{letters.map(e=><option key={e.id} value={e.id}>{e.format.toUpperCase()} · wersja {e.version} · {e.id.slice(0,8)}</option>)}</select></label>{docs.map(e=><label className="check" key={e.id}><input type="checkbox" checked={selected.includes(e.id)} onChange={v=>setSelected(v.target.checked?[...selected,e.id]:selected.filter(x=>x!==e.id))}/>Kopia załącznika: {documents.find(d=>d.id===e.document_id)?.name||e.document_id.slice(0,8)} · wersja {e.version}</label>)}<button className="button secondary" disabled={!letter} onClick={()=>action(()=>downloadBlob('/cases/'+caseId+'/export-packages',{letter_export_id:letter,attachment_export_ids:selected},'odpowiedz-z-zalacznikami.zip'))}><Download size={16}/>Pobierz pakiet ZIP</button></div>}
function DocumentList({docs,onDoc,emptyText="Dodaj pierwszy dokument do tej sprawy."}:{docs:Doc[];onDoc:(d:Doc)=>void;emptyText?:string}){return docs.length?<div className="documents">{docs.map(d=><button className="document-row" key={d.id} onClick={()=>onDoc(d)}><div className="file-icon"><FileText size={22}/></div><div><b>{d.kind==='knowledge'&&d.metadata?.title?d.metadata.title:d.name}</b><small>{d.kind==='knowledge'&&(d.metadata?.effective_from||d.metadata?.effective_to)?`Obowiązuje ${d.metadata.effective_from?'od '+date(d.metadata.effective_from):''}${d.metadata.effective_to?' do '+date(d.metadata.effective_to):''} · `:''}{d.kind==='knowledge'?'Baza wiedzy':d.kind==='request'?'Wniosek':d.kind==='attachment'?'Załącznik':'Materiał jednostki'}{d.metadata?.ocr_low_confidence?' · niska pewność OCR':''} · {d.pages} {d.pages===1?'strona':d.pages%10>=2&&d.pages%10<=4&&(d.pages%100<10||d.pages%100>=20)?'strony':'stron'} · {d.state==='ready'?(d.active?'Zatwierdzony':d.metadata?.deactivated?'Wyłączony z bazy '+date(d.metadata.deactivated):'Odczyt do sprawdzenia'):d.state==='failed'?'Błąd odczytu — wgraj poprawiony plik':'Przetwarzanie'}</small></div><span className={'badge '+(d.active?'zakonczona':'later')}>{d.active?'Zatwierdzony':d.metadata?.deactivated?'Wyłączony':'Sprawdź'}</span><ChevronRight size={16}/></button>)}</div>:<Empty text={emptyText}/>}
function EditCase({c,onClose}:{c:Case;onClose:()=>void}){const [value,setValue]=useState(c);const [questions,setQuestions]=useState(c.questions.map(q=>q.text).join('\n\n'));return <Modal title="Dane sprawy i pytania" onClose={onClose}><form className="modal-body" onSubmit={e=>{e.preventDefault();action(async()=>{const qs=questions.split(/\n\s*\n/).filter(Boolean).map((text,i)=>({id:'q'+(i+1),text,status:'brak_materialu'}));await api('/cases/'+c.id,'PATCH',{reference:value.reference,title:value.title,applicant:value.applicant,received:value.received,owner:value.owner,delivery:value.delivery,units:value.units,version:c.version,questions:qs});onClose()})}}>{[['reference','Sygnatura'],['title','Przedmiot'],['applicant','Wnioskodawca'],['received','Data wpływu'],['owner','Prowadzący'],['delivery','Żądana forma udostępnienia']].map(([k,l])=><label key={k}>{l}<input type={k==='received'?'date':'text'} value={(value as any)[k]} onChange={e=>setValue({...value,[k]:e.target.value})}/></label>)}<label>Pytania (oddziel pustym wierszem)<textarea rows={8} value={questions} onChange={e=>setQuestions(e.target.value)}/></label><button className="button primary">Zapisz zmiany</button></form></Modal>}
function DeadlineModal({c,onClose}:{c:Case;onClose:()=>void}){const [value,setValue]=useState({deadline:c.deadline,notified_on:localDay(),reason:'',basis:'art. 13 ust. 2 UDIP'});return <Modal title="Odnotowanie zmiany terminu" onClose={onClose}><form className="modal-body" onSubmit={e=>{e.preventDefault();action(async()=>{await api('/cases/'+c.id+'/deadline-events','POST',{...value,version:c.version});onClose()})}}><p className="notice">Wypełnij po faktycznym powiadomieniu wnioskodawcy poza aplikacją.</p>{[['deadline','Nowy termin','date'],['notified_on','Data powiadomienia','date'],['reason','Powód opóźnienia','text'],['basis','Podstawa','text']].map(([k,l,type])=><label key={k}>{l}<input type={type} value={(value as any)[k]} onChange={e=>setValue({...value,[k]:e.target.value})} required/></label>)}<button className="button primary">Zapisz historię zmiany</button></form></Modal>}
function SentModal({c,onClose}:{c:Case;onClose:()=>void}){const [answered,setAnswered]=useState(localDay());const [delivery,setDelivery]=useState('');return <Modal title="Potwierdzenie udostępnienia informacji" onClose={onClose}><form className="modal-body" onSubmit={e=>{e.preventDefault();action(async()=>{await api('/cases/'+c.id+'/sent','POST',{version:c.version,answered,delivery});onClose()})}}><p className="notice">Ta czynność tylko zapisuje datę rzeczywistego udostępnienia. Nie wysyła dokumentów.</p><label>Data udostępnienia<input type="date" required value={answered} onChange={e=>setAnswered(e.target.value)}/></label><label>Sposób udostępnienia<input required placeholder="np. e-mail, e-Doręczenia, wgląd" value={delivery} onChange={e=>setDelivery(e.target.value)}/></label><button className="button primary">Potwierdź i zakończ sprawę</button></form></Modal>}
function DraftEditor({initial,onClose}:{initial:Draft;onClose:()=>void}){const [d,setD]=useState(initial);const [text,setText]=useState(d.text);const [coverage,setCoverage]=useState(d.coverage);const [phrase,setPhrase]=useState('');const [exported,setExported]=useState<any>(null);const [busy,setBusy]=useState(false);const editor=useEditor({extensions:[StarterKit],content:{type:'doc',content:d.text.split('\n').map(t=>({type:'paragraph',content:t?[{type:'text',text:t}]:[]}))},onUpdate:({editor})=>setText(editor.getText({blockSeparator:'\n'}))});const dirty=text!==d.text||JSON.stringify(coverage)!==JSON.stringify(d.coverage);const setDraft=(r:Draft)=>{setD(r);setCoverage(r.coverage);setExported(null)};const spans=Array.from(d.text);async function changeSpans(redactions:Redaction[]){await action(async()=>setDraft(await api('/drafts/'+d.id+'/redactions','PATCH',{version:d.version,redactions})))}
 return <Modal title="Projekt odpowiedzi · weryfikacja i anonimizacja" wide onClose={onClose}><div className="draft-layout"><div className="draft-main"><div className="editor-toolbar"><span className="badge later">Wersja {d.version}</span><button className="button secondary" disabled={!dirty||busy} onClick={async()=>{setBusy(true);await action(async()=>setDraft(await api('/drafts/'+d.id,'PATCH',{version:d.version,text,coverage})));setBusy(false)}}>Zapisz zmiany</button><span className="muted">{dirty?'Niezapisane zmiany':d.approved_version===d.version?'Wersja zatwierdzona':'Wersja do sprawdzenia'}</span></div><EditorContent editor={editor} className="letter-editor"/><RedactionPreview text={d.text} redactions={d.redactions} disabled={dirty} onChange={changeSpans}/><div className="evidence"><h3>Źródła wykorzystane w projekcie</h3>{d.evidence.map((s:any)=><details key={s.id}><summary>{s.id}</summary><p>{s.excerpt}</p></details>)}{!d.evidence.length&&<p className="muted">Szkic ręczny — operator weryfikuje źródła w materiałach sprawy.</p>}</div></div><div className="draft-sidebar"><h3>Kompletność odpowiedzi</h3>{coverage.map((a:any,i:number)=><div className="coverage" key={a.question_id}><strong>Pytanie {i+1}</strong><label className="check"><input type="checkbox" checked={a.reviewed} onChange={e=>setCoverage(coverage.map(x=>x.question_id===a.question_id?{...x,reviewed:e.target.checked}:x))}/>Treść i źródła sprawdzone</label><label>Braki do uzupełnienia<textarea rows={2} value={(a.missing||[]).join('\n')} onChange={e=>setCoverage(coverage.map(x=>x.question_id===a.question_id?{...x,missing:e.target.value.split('\n').filter(Boolean)}:x))}/></label></div>)}<h3>Anonimizacja</h3><p className="micro">System automatycznie proponuje dane do ukrycia przy każdym zapisie pisma. Każdą propozycję trzeba rozpatrzyć przed zatwierdzeniem.</p><button className="button secondary full" disabled={dirty} onClick={()=>action(async()=>setDraft(await api('/drafts/'+d.id+'/redaction-scan','POST')))}><Search size={15}/>Wykryj ponownie</button>{d.redactions.map((r,i)=><div key={i} className={'redaction '+r.state}><b>{spans.slice(r.start,r.end).join('')}</b><small>{r.category} · {r.reason}</small><div className="inline"><button disabled={dirty} className={'button tiny '+(r.state==='accepted'?'primary':'secondary')} onClick={()=>changeSpans(d.redactions.map((x,j)=>j===i?{...x,state:'accepted'}:x))}>Ukryj</button><button disabled={dirty} className="button tiny secondary" onClick={()=>changeSpans(d.redactions.map((x,j)=>j===i?{...x,state:'rejected'}:x))}>Pozostaw</button></div></div>)}<label>Dodaj tekst do ukrycia<input value={phrase} onChange={e=>setPhrase(e.target.value)} placeholder="Dokładny fragment pisma"/></label><button className="button secondary full" disabled={dirty||!phrase} onClick={()=>{const range=textRange(d.text,phrase);if(!range){showError('Nie znaleziono tego fragmentu w zapisanym piśmie.');return}changeSpans([...d.redactions,{...range,state:'accepted',category:'ręcznie',reason:'Wybór operatora'}]);setPhrase('')}}>Ukryj wskazany fragment</button>{dirty&&<p className="notice warning">Zapisz zmiany przed anonimizacją i zatwierdzeniem.</p>}<button className="button primary full" disabled={dirty||busy} onClick={()=>action(async()=>setDraft(await api('/drafts/'+d.id+'/approve','POST',{version:d.version,confirmed:true})))}><ShieldCheck size={16}/>Zatwierdź bieżącą wersję</button><div className="export-grid">{['pdf','docx','txt','doc'].map(f=><button key={f} disabled={dirty||d.approved_version!==d.version} className="button secondary" onClick={()=>action(async()=>setExported(await api('/drafts/'+d.id+'/exports?format='+f,'POST')))}><Download size={14}/>{f.toUpperCase()}</button>)}</div>{exported&&<a className="button primary full" href={exported.url}>Pobierz {exported.format.toUpperCase()}</a>}</div></div></Modal>
}
function DocumentModal({doc:initial,onClose}:{doc:Doc;onClose:()=>void}){const [doc,setDoc]=useState(initial);const [tab,setTab]=useState('text');const [content,setContent]=useState(doc.text);const [meta,setMeta]=useState({title:doc.metadata.title||doc.name,source:doc.metadata.source||'',effective_from:doc.metadata.effective_from||'',effective_to:doc.metadata.effective_to||''});const [page,setPage]=useState(1);const [masks,setMasks]=useState<any[]>([]);const [reviewed,setReviewed]=useState<number[]>([]);const [reviewVersion,setReviewVersion]=useState(0);const [drag,setDrag]=useState<number[]|null>(null);const [preview,setPreview]=useState<any>(null);const [saved,setSaved]=useState(true);const container=useRef<HTMLDivElement>(null);const current=useQuery({queryKey:['document-review',doc.id],queryFn:()=>api('/documents/'+doc.id+'/review'),refetchInterval:['ready','failed'].includes(doc.state)?false:2000});useEffect(()=>{if(current.data){setDoc(current.data.document);setContent(current.data.document.text)}},[current.data?.document.id,current.data?.document.version,current.data?.document.state]);useEffect(()=>{if(current.data){setMasks(current.data.review.masks);setReviewed(current.data.review.reviewed_pages);setReviewVersion(current.data.review.version)}},[current.data?.document.id,current.data?.review.version]);useEffect(()=>{if(current.data)setPreview(current.data.exports.find((e:any)=>e.current)||null)},[current.data?.exports]);function point(e:React.PointerEvent){const r=container.current!.getBoundingClientRect();return [Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))]}const wordProposals=()=>action(async()=>{const r=await api('/documents/'+doc.id+'/pages/'+page+'/proposals');if(!r.ocr){showError('Ta strona ma warstwę tekstową bez położeń OCR. Zaznacz dane ręcznie na obrazie.');return}const fresh=r.masks.filter((m:any)=>!masks.some(x=>x.page===m.page&&JSON.stringify(x.box)===JSON.stringify(m.box)));if(!fresh.length){showError('Brak nowych propozycji na tej stronie. Sprawdź podpisy i dane ręcznie.');return}setMasks([...masks,...fresh]);setSaved(false);setPreview(null)});return <Modal title={doc.name} onClose={onClose} wide><div className="tabs modal-tabs"><button className={tab==='text'?'selected':''} onClick={()=>setTab('text')}>Odczyt i zatwierdzenie</button><button disabled={!doc.has_pdf} className={tab==='redact'?'selected':''} onClick={()=>setTab('redact')}>Strony i anonimizacja PDF</button></div>{tab==='text'?<div className="modal-body">{doc.metadata?.ocr_low_confidence&&<p className="notice warning">Niska pewność OCR ({doc.metadata.ocr_confidence}%) — prawdopodobnie pismo odręczne. Przepisz treść z podglądu strony przed zatwierdzeniem.</p>}<p className="notice">{doc.active?'Dokument jest zatwierdzony. Ponowny zapis zmienia jego wersję i wymaga ponownej weryfikacji powiązanych eksportów.':'Sprawdź treść przed udostępnieniem jej wyszukiwaniu i generatorowi odpowiedzi.'}</p>{doc.kind==='knowledge'&&<div className="form-grid">{[['title','Tytuł'],['source','Źródło / URL'],['effective_from','Obowiązuje od'],['effective_to','Obowiązuje do']].map(([k,l])=><label key={k}>{l}<input type={k.startsWith('effective')?'date':'text'} value={(meta as any)[k]} onChange={e=>setMeta({...meta,[k]:e.target.value})}/></label>)}</div>}<label>Tekst dokumentu<textarea rows={18} value={content} onChange={e=>setContent(e.target.value)}/></label><button disabled={doc.state!=='ready'} className="button primary" onClick={()=>action(async()=>{setDoc(await api('/imports/'+doc.id+'/confirm','POST',{version:doc.version,text:content,metadata:meta}));showError('Zatwierdzono dokument. Zlecono aktualizację indeksu.');queryClient.invalidateQueries({queryKey:['document-review',doc.id]})})}><Check size={16}/>Zatwierdź odczyt</button>{doc.kind==='request'&&!doc.case_id&&<p className="notice">Rejestrację nowego wniosku dokończ w formularzu „Nowy wniosek”.</p>}</div>:<div className="attachment-layout"><div className="attachment-main"><div className="page-controls"><button aria-label="Poprzednia strona" className="icon" disabled={page===1} onClick={()=>setPage(page-1)}><ChevronLeft/></button><b>Strona {page} z {doc.pages}</b><button aria-label="Następna strona" className="icon" disabled={page===doc.pages} onClick={()=>setPage(page+1)}><ChevronRight/></button><span className="muted">Przeciągnij, aby zaznaczyć obszar do usunięcia</span></div><div ref={container} className="page-image" onPointerDown={e=>{if(e.button!==0)return;e.currentTarget.setPointerCapture(e.pointerId);setDrag(point(e))}} onPointerUp={e=>{if(!drag)return;const end=point(e);const box=[Math.min(drag[0],end[0]),Math.min(drag[1],end[1]),Math.max(drag[0],end[0]),Math.max(drag[1],end[1])];if(box[2]-box[0]>.003&&box[3]-box[1]>.003){setMasks([...masks,{page,box,state:'accepted',category:'ręcznie'}]);setSaved(false);setPreview(null)}setDrag(null)}}><img draggable={false} src={'/api/documents/'+doc.id+'/pages/'+page} alt={'Strona '+page+' dokumentu źródłowego'}/>{masks.filter(m=>m.page===page&&m.state!=='rejected').map((m,i)=><div className={'mask '+m.state} key={i} style={{left:m.box[0]*100+'%',top:m.box[1]*100+'%',width:(m.box[2]-m.box[0])*100+'%',height:(m.box[3]-m.box[1])*100+'%'}}/>)}</div></div><div className="draft-sidebar"><h3>Przegląd stron</h3><p className="micro">Sprawdź tekst, podpisy i obrazy. Czarne obszary zostaną trwale usunięte z kopii PDF.</p><button className="button secondary full" onClick={wordProposals}>Znajdź propozycje z OCR</button><label className="check"><input type="checkbox" checked={reviewed.includes(page)} onChange={e=>{setReviewed(e.target.checked?[...reviewed,page]:reviewed.filter(p=>p!==page));setSaved(false)}}/>Strona {page} sprawdzona</label><p className="micro">Sprawdzono {reviewed.length}/{doc.pages} stron</p>{masks.map((m,i)=><div key={i} className="redaction"><b>Strona {m.page} · {m.category}</b><div className="inline">{m.state==='proposed'&&<button className="button tiny primary" onClick={()=>{setMasks(masks.map((x,j)=>j===i?{...x,state:'accepted'}:x));setSaved(false);setPreview(null)}}>Ukryj</button>}<button className="button tiny secondary" onClick={()=>{setMasks(masks.filter((_,j)=>j!==i));setSaved(false);setPreview(null)}}>Usuń zaznaczenie</button></div></div>)}<button className="button secondary full" onClick={()=>action(async()=>{const r=await api('/documents/'+doc.id+'/redactions','PATCH',{version:reviewVersion,masks,reviewed_pages:reviewed});setReviewVersion(r.version);setSaved(true);setPreview(null)})}>Zapisz przegląd</button><button disabled={!saved||reviewed.length!==doc.pages} className="button primary full" onClick={()=>action(async()=>{setPreview(await api('/documents/'+doc.id+'/redacted-exports','POST'))})}><ShieldCheck size={16}/>Utwórz czystą kopię PDF</button>{preview&&saved&&<><a className="button secondary full" href={preview.url+'?inline=true'} target="_blank" rel="noreferrer">Otwórz wynik do sprawdzenia</a><button disabled={preview.approved} className="button primary full" onClick={()=>action(async()=>{await api('/document-exports/'+preview.id+'/approve','POST',{version:preview.version,confirmed:true});setPreview({...preview,approved:true})},'Zatwierdzono sprawdzoną kopię załącznika.')}><Check size={16}/>{preview.approved?'Kopia zatwierdzona':'Potwierdź przegląd wyniku'}</button></>}<p className="micro">Kopia jest obrazowym PDF, bez pierwotnej warstwy tekstowej i podpisu cyfrowego. Oryginał pozostaje w aktach.</p></div></div>}</Modal>}
function Knowledge({onDoc,admin}:{onDoc:(d:Doc)=>void;admin:boolean}){const docs=useQuery<Doc[]>({queryKey:['knowledge'],queryFn:()=>api('/knowledge/documents'),refetchInterval:5000});return <><div className="page-heading"><div><span className="eyebrow">LOKALNE ŹRÓDŁA</span><h1>Baza wiedzy</h1><p>Ustawy, procedury i materiały wykorzystywane w obsłudze spraw.</p></div>{admin&&<FileButton label="Dodaj dokument wiedzy" onFile={f=>action(()=>upload('/knowledge/documents',f))}/>}</div><div className="notice"><BookOpen size={18}/><span>Nowe źródło wymaga przeglądu i zatwierdzenia. Aktualizuj akty prawne przez dodanie nowej wersji i wyłączenie poprzedniej.</span></div><section className="card pad"><DocumentList docs={docs.data||[]} onDoc={onDoc} emptyText="Brak dokumentów w bazie wiedzy."/>{admin&&docs.data?.filter(d=>d.active).map(d=><div className="deactivate" key={d.id}><span>{d.name}</span><button className="button subtle" onClick={()=>action(()=>api('/knowledge/documents/'+d.id+'/deactivate','POST'),'Wyłączono źródło z aktywnej bazy.')}>Wyłącz źródło</button></div>)}</section></>}
function Diagnostics({data,jobs}:{data:any;jobs:Job[]}){const names:Record<string,string>={database:'Baza PostgreSQL',ollama:'Silnik Ollama',model:'Model Bielik',embeddings:'Model wyszukiwania E5',ocr:'Polski OCR',word:'Konwersja Word',worker:'Proces roboczy',ner:'Polski model NER'};return <><div className="page-heading"><div><span className="eyebrow">ŚRODOWISKO APLIKACJI</span><h1>Diagnostyka</h1><p>Dostępność lokalnych usług i historia zadań przetwarzania.</p></div></div><div className="diagnostic-grid">{Object.entries(data?.checks||{}).map(([key,value])=><div className="card diagnostic" key={key}>{value?<CheckCircle2 className="green"/>:<AlertCircle className="amber"/>}<div><h3>{names[key]||key}</h3><p>{value?'Gotowe':'Wymaga konfiguracji lub uruchomienia'}</p></div></div>)}</div><section className="card pad"><h2>Zadania przetwarzania</h2><p className="muted">Model: {data?.model} · brak przełączania do usług chmurowych</p>{jobs.map(j=><div className="job-row" key={j.id}><span className={'badge '+(j.status==='failed'?'overdue':j.status==='done'?'zakonczona':'later')}>{({queued:'w kolejce',running:'w trakcie',done:'gotowe',failed:'błąd'} as any)[j.status]||j.status}</span><b>{j.kind==='draft'?'Projekt odpowiedzi':j.kind==='index'?'Indeksowanie':'Odczyt dokumentu'}</b><span>{j.result.error||j.progress}</span></div>)}</section></>}
function CalendarImport({onClose}:{onClose:()=>void}){const [rows,setRows]=useState<any[]>([]);const [confirmed,setConfirmed]=useState(false);return <Modal title="Import kalendarium z XLSX" onClose={onClose} wide><div className="modal-body"><p className="notice">Weryfikuj wszystkie wartości. Daty sprzeczne z wpływem trzeba poprawić; plik źródłowy pozostaje niezmieniony.</p><FileButton label="Wybierz kalendarium" accept=".xlsx" onFile={f=>action(async()=>{const r=await upload('/calendar-imports/preview',f);setRows(r.rows)})}/>{rows.length>0&&<><div className="import-grid">{rows.map((r,i)=><div className="calendar-import-row" key={i}><b>{r.reference}</b><small>{r.title}</small>{r.warnings.map((w:string)=><p key={w} className="error">{w}</p>)}<div className="form-grid">{[['received','Wpływ'],['deadline','Termin'],['answered','Odpowiedź']].map(([key,label])=><label key={key}>{label}<input type="date" value={r[key]||''} onChange={e=>setRows(rows.map((x,j)=>i===j?{...x,[key]:e.target.value||null}:x))}/></label>)}</div></div>)}</div><label className="check"><input type="checkbox" checked={confirmed} onChange={e=>setConfirmed(e.target.checked)}/>Sprawdziłem dane i poprawiłem rozbieżności.</label><button className="button primary" disabled={!confirmed} onClick={()=>action(async()=>{const res=await api('/calendar-imports/confirm','POST',{confirmed,rows:rows.map(({source_deadline,...r})=>r)});onClose();showError(`Zaimportowano ${res.count} spraw.`+(res.skipped?.length?` Pominięto istniejące: ${res.skipped.join(', ')}.`:''))})}>Zaimportuj {rows.length} spraw</button></>}</div></Modal>}
// Keep one React root when Vite reevaluates this entry during development.
const container=document.getElementById('root')! as HTMLElement & {umbRoot?:ReturnType<typeof createRoot>}
const root=container.umbRoot??(container.umbRoot=createRoot(container))
root.render(<React.StrictMode><QueryClientProvider client={queryClient}><App/></QueryClientProvider></React.StrictMode>)
